#!/usr/bin/env bash
#
# test-log-report.sh — run tools/log-report.py and assert key facts. Fails (exit 1) on any mismatch.
#
# Inputs:
#   tools/testdata/logs/            GENERATED by a Kotlin test from real EventLogger output; never hand-edit.
#   android/app/src/test/resources/native-events-golden.json   real Rust event shapes (read-only here)
#   small synthetic logs built below for cancel / ordering cases
#
# Usage: tools/test-log-report.sh
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
FIX="$ROOT/tools/testdata/logs"
GOLDEN="$ROOT/android/app/src/test/resources/native-events-golden.json"
TMP="$(mktemp -d)"
trap 'rm -rf "$TMP"' EXIT
RPT="$ROOT/tools/log-report.py"

FAILED=0
expect() {  # expect <report-file> <fixed string that must appear>
  if ! grep -qF -- "$2" "$1"; then echo "FAIL: $(basename "$1") lacks: $2" >&2; FAILED=1; fi
}
reject() {  # reject <report-file> <fixed string that must NOT appear>
  if grep -qF -- "$2" "$1"; then echo "FAIL: $(basename "$1") contains: $2" >&2; FAILED=1; fi
}

# ---- 1. generated fixture ----------------------------------------------------
R="$TMP/fixture.txt"
python3 "$RPT" "$FIX" > "$R"
expect "$R" "lines=36 unparseable=1 processes=2 sessions=3 transfers=2 failures=4"
expect "$R" "P1 pid=4222"
expect "$R" "P2 pid=4301"
expect "$R" "S e5f60718 P1"
expect "$R" "usb=1921:21889 dev_bytes=500107862016 sector=512 flush=true max_xfer=1048576 fs=btrfs cipher=aes-xts-plain64/512"
expect "$R" "P1 x1 import 1 52428800 4230 11.82 completed - - -"
expect "$R" "P2 x2 export 1 104857600 5210 19.19 failed 7 read LuksException"
expect "$R" "-- F1 unlock_fail P1 seq=2"
expect "$R" "-- F2 health P1 seq=5"
expect "$R" "finding leaked_extent n=3"
expect "$R" "-- F3 native_err P2 seq=12"
expect "$R" "-- F4 xfer_end P2 seq=13"
expect "$R" "native_ring (3 records, xfer=2):"
expect "$R" "kind=scsi_command lba=204800 blocks=2048"
expect "$R" "rs native kind=usb_timeout nseq=101"          # native cause shown in the failure context
expect "$R" "rs native kind=usb_state_transition nseq=104"
expect "$R" "from=healthy nt=1790003665003 to=dead"        # nt is displayed
expect "$R" "usb_timeout=1 usb_reset=1 scsi_reset=0 panics=0 native_dropped=0 ring_lines=3"
expect "$R" "usb reset kinds: clear_halt_in status=-19 x1"
expect "$R" "usb state transitions: healthy->dead x1"
expect "$R" "seq gaps=1 lines_lost_to_gaps=1 dropped_kt=5 dropped_rs=0"
expect "$R" "gap P2 after seq=8 next seq=10 lost=1"
expect "$R" "unparseable lines=1"
expect "$R" "events.0.jsonl:7 "
expect "$R" "cancelled (not failures): transfers=0 native_err_code19=0"
if grep -E 'preceding ([2-9][0-9]|[1-9][0-9]{2,}) line' "$R" >/dev/null; then
  echo "FAIL: a failure lists more than 20 preceding kt lines" >&2; FAILED=1
fi

# ---- 2. --json agrees --------------------------------------------------------
python3 - "$RPT" "$FIX" <<'PY' || FAILED=1
import json, subprocess, sys
d = json.loads(subprocess.run([sys.executable, sys.argv[1], sys.argv[2], "--json"],
                              capture_output=True, text=True, check=True).stdout)
ok = (len(d["failures"]) == 4 and len(d["transfers"]) == 2
      and d["dropped"] == {"kt": 5, "rs": 0, "lost_to_seq_gaps": 1}
      and len(d["meta"]["unparseable"]) == 1
      and [t["state"] for t in d["transfers"]] == ["completed", "failed"])
if not ok:
    print("FAIL: --json content mismatch", file=sys.stderr); sys.exit(1)
PY

# ---- 3. unreadable input -> exit 2 -------------------------------------------
set +e
python3 "$RPT" /nonexistent/path >/dev/null 2>&1
[ $? -eq 2 ] || { echo "FAIL: unreadable input did not exit 2" >&2; FAILED=1; }
set -e

# ---- 4. golden native events, wrapped as the app writes them ------------------
python3 - "$GOLDEN" "$TMP/golden.jsonl" <<'PY'
import json, sys
g = json.load(open(sys.argv[1]))
out = [json.dumps({"t": 1700000100000, "seq": 1, "sid": "-", "src": "kt", "ev": "process_start", "n": 1})]
for i, e in enumerate(g["events"], 2):
    e = dict(e); nt = e.pop("t"); kind = e.pop("ev")
    out.append(json.dumps({"t": 1700000100000 + i, "seq": i, "sid": "aaaaaaaa", "src": "rs",
                           "ev": "native", "kind": kind, "nt": nt, **e}))
open(sys.argv[2], "w").write("\n".join(out) + "\n")
PY
G="$TMP/golden.txt"
python3 "$RPT" "$TMP/golden.jsonl" > "$G"
expect "$G" "unparseable=0"
expect "$G" "usb_timeout=1 usb_reset=1 scsi_reset=1 panics=1 native_dropped=0"
expect "$G" "usb reset kinds: bot_mass_storage_reset status=0 x1"
expect "$G" "usb state transitions: healthy->dead x1; drain_aborted=1"
expect "$G" "scsi not-passed / sense: status=failed sense_key=3 x1"   # the passed result is not listed
expect "$G" "ext4 left dirty: resync_ok=false cleanup_code=9 x1; resync_ok=true cleanup_code=- x1; flush_failed=1"
expect "$G" "panics at: src.fs.ext4.file.rs:10 x1"
expect "$G" "fs errors: btrfs_error stage=commit code=9 x1; ext4_error stage=finish_file code=5 x1"

# ---- 5. cancellation is not a failure; native lines ordered by nt -------------
cat > "$TMP/synth.jsonl" <<'JL'
{"t":1000,"seq":1,"sid":"-","src":"kt","ev":"process_start","n":7}
{"t":1010,"seq":2,"sid":"aaaaaaaa","src":"kt","ev":"xfer_queued","xfer":1,"op":"import","n":1,"bytes":10}
{"t":1020,"seq":3,"sid":"aaaaaaaa","src":"kt","ev":"native_err","op":"import","exc":"LuksException","code":19,"xfer":1,"stage":"write"}
{"t":1030,"seq":4,"sid":"aaaaaaaa","src":"kt","ev":"xfer_end","xfer":1,"state":"cancelled","ms":20,"bytes":5,"n":1}
{"t":1040,"seq":5,"sid":"aaaaaaaa","src":"kt","ev":"xfer_queued","xfer":2,"op":"import","n":1,"bytes":10}
{"t":1050,"seq":6,"sid":"aaaaaaaa","src":"kt","ev":"xfer_end","xfer":2,"state":"failed","code":7,"stage":"write","exc":"LuksException","ms":9,"bytes":1,"n":1}
{"t":3050,"seq":7,"sid":"aaaaaaaa","src":"rs","ev":"native","kind":"usb_timeout","nseq":1,"nt":1045,"elapsed_ms":5000,"ep":1}
{"t":3051,"seq":8,"sid":"aaaaaaaa","src":"rs","ev":"native","kind":"usb_submit","nseq":2,"nt":1046,"ep":1}
JL
S="$TMP/synth.txt"
python3 "$RPT" "$TMP/synth.jsonl" > "$S"
expect "$S" "failures=1"
expect "$S" "cancelled (not failures): transfers=1 native_err_code19=1"
expect "$S" "-- F1 xfer_end P1 seq=6"
reject "$S" "-- F1 native_err"
# usb_timeout was drained 2 s late (t=3050, nt=1045) but must precede the xfer_end it caused:
expect "$S" "kind=usb_timeout nseq=1"
reject "$S" "kind=usb_submit"                                         # hot kind filtered from context
python3 - "$S" <<'PY' || FAILED=1
import sys
t = open(sys.argv[1]).read()
blk = t[t.index("-- F1"):t.index("== NATIVE")]
pre = blk.index("preceding")
if not (pre < blk.index("xfer_queued xfer=2") < blk.index("kind=usb_timeout")):
    print("FAIL: late-drained native line not ordered into failure context", file=sys.stderr); sys.exit(1)
PY

if [ "$FAILED" -ne 0 ]; then exit 1; fi
echo "ok: log-report fixture checks passed"
